import numpy as np
from scipy.spatial import ConvexHull
from scipy.ndimage import label
from scipy.optimize import least_squares
from scipy.spatial.transform import Rotation
from PIL import Image
from vision3 import cp,cr,foc
uv=np.array([[129,178],[147,174],[193,209],[171,214]],float);world=[]
for u,v in uv:
 ray=cr.T@np.array([(u-128)/foc,-(v-128)/foc,1]);world.append(cp+ray*((.38-cp[2])/ray[2]))
world=np.array(world);center=world.mean(0);v1=(world[0]-world[1]+world[3]-world[2])/2;v2=(world[3]-world[0]+world[2]-world[1])/2;w=np.linalg.norm(v1);l=np.linalg.norm(v2);v1/=w;v2/=l;v2-=v1*(v1@v2);v2/=np.linalg.norm(v2);base=np.array([v1,v2,np.array([0,0,1])]).T;corners=np.array([[w/2,-l/2,0],[-w/2,-l/2,0],[-w/2,l/2,0],[w/2,l/2,0]])@base.T
sphere=np.array([.108,.005,.18]);offset=center-sphere

def project(ang):
 R=Rotation.from_euler('xy',ang).as_matrix();pts=sphere+((offset+corners)@R.T);xyz=(pts-cp)@cr.T;return np.c_[128+foc*xyz[:,0]/xyz[:,2],128-foc*xyz[:,1]/xyz[:,2]]
def polygon(im):
 gray=im[:,:,0];roi=np.zeros((256,256),bool);roi[145:232,105:223]=True;vals=gray[roi&(gray>=130)&(gray<=201)];cnt=np.bincount(vals,minlength=256);mode=np.argmax(cnt);mask=roi&(gray>=mode-1)&(gray<=mode+1);lab,n=label(mask);sizes=np.bincount(lab.ravel());sizes[0]=0;mask=np.isin(lab,np.where(sizes>20)[0]);y,x=np.where(mask)
 if len(x)<50:raise ValueError('board missing')
 pts=np.c_[x,y].astype(float);return pts[ConvexHull(pts).vertices],mode

def edgedistance(points,poly):
 a=poly;b=np.roll(poly,-1,axis=0);v=b-a;t=np.clip(np.sum((points[:,None,:]-a[None,:,:])*v[None,:,:],axis=2)/np.sum(v*v,axis=1)[None,:],0,1);dif=points[:,None,:]-(a[None,:,:]+t[:,:,None]*v[None,:,:]);return np.min(np.linalg.norm(dif,axis=2),axis=1)
class BoardTracker:
 def __init__(self):self.ang=np.zeros(2);self.vel=np.zeros(2)
 def get(self,im):
  poly,mode=polygon(im)
  def fun(ang):
   q=project(ang);return np.r_[edgedistance(poly,q),edgedistance(q,poly)]
  result=least_squares(fun,self.ang,bounds=(-1.1,1.1),loss='soft_l1',f_scale=2,max_nfev=30);new=result.x;self.vel=.6*self.vel+.4*(new-self.ang)/.02;self.ang=new;return new.copy(),self.vel.copy(),mode,np.mean(result.fun**2)
if __name__=='__main__':
 print('geom',center,w,l,base)
 for name in ['room_camera','current']:
  im=np.array(Image.open('/app/output/'+name+'.png'));bt=BoardTracker();print(name,bt.get(im));print('poly',polygon(im));print('fit',project(bt.ang))
