import numpy as np,json
from geometry import kin,s,idx,names,mass,com
from scipy.optimize import brentq
from scipy.linalg import expm,solve_discrete_are
mboard=14.4;kp=np.array([400.,600.,80.]);damp=np.array([40.,60.,4.]);L=np.array([[0,0,1,0],[0,0,0,1],[1,-1,-1,-1]],float)
def ry(a):return np.array([[np.cos(a),0,np.sin(a)],[0,1,0],[-np.sin(a),0,np.cos(a)]])
def configuration(x):
 b,p,h,k=x;a=b-p-h-k;qq=np.zeros(19);qq[[2,7]]=h;qq[[3,8]]=k;qq[[4,9]]=a;cl,ft,T=kin(qq)
 sole=[]
 for name,box in s['links']['feet'].items():
  point=np.mean(box,axis=0);point[2]=box[0][2];t=T[idx[name]];sole.append(t[:3,:3]@point+t[:3,3])
 ft=np.mean(sole,axis=0);P=ry(p);B=ry(b);anchor=B@np.array([-.0165,0,.20]);root=anchor-P@ft
 points=np.array([root+P@(t[:3,:3]@cc+t[:3,3]) for t,cc in zip(T,com)])
 board=B@np.array([-.0343,-.0392,.20]);return points,board,root,qq

def potential(x):
 points,board,*_=configuration(x);return 9.81*(mass@points[:,2]+mboard*board[2])
def totalcom(x):
 points,board,*_=configuration(x);return (mass@points+mboard*board)/(mass.sum()+mboard)
def metric(x):
 eps=1e-5;J=[];JB=[]
 for j in range(4):
  xp=x.copy();xm=x.copy();xp[j]+=eps;xm[j]-=eps;pp,bp,*_=configuration(xp);pm,bm,*_=configuration(xm);J.append((pp-pm)/(2*eps));JB.append((bp-bm)/(2*eps))
 J=np.stack(J,axis=-1);JB=np.stack(JB,axis=-1);M=np.einsum('i,iaj,iak->jk',mass,J,J)+mboard*(JB.T@JB)
 # intrinsic rotation inertia: torso/pelvis, two thighs, two shanks, two feet
 for I,j in [(.65,np.array([0,1,0,0.])),(.12,np.array([0,1,1,0.])),(.06,np.array([0,1,1,1.])),(.02,np.array([1,0,0,0.]))]:M+=I*np.outer(j,j)
 M[0,0]+=mboard*.3**2/12+.12
 return M

def gradient(x):
 eps=1e-5;return np.array([(potential(x+np.eye(4)[j]*eps)-potential(x-np.eye(4)[j]*eps))/(2*eps) for j in range(4)])
def hessian(x):
 eps=1e-4;return np.array([(gradient(x+np.eye(4)[j]*eps)-gradient(x-np.eye(4)[j]*eps))/(2*eps) for j in range(4)]).T

def model(k=.8):
 h=brentq(lambda h:totalcom(np.array([0,0,h,k]))[0],-.8,.4);xe=np.array([0.,0.,h,k]);G=gradient(xe);tau=np.linalg.lstsq(L.T,G,rcond=None)[0];ue=L@xe+tau/kp
 M=metric(xe);H=hessian(xe);A=np.zeros((8,8));A[:4,4:]=np.eye(4);A[4:,:4]=np.linalg.solve(M,-H-L.T@np.diag(kp)@L);A[4:,4:]=np.linalg.solve(M,-L.T@np.diag(damp)@L);B=np.zeros((8,3));B[4:]=np.linalg.solve(M,L.T@np.diag(kp));E=np.zeros((11,11));E[:8,:8]=A;E[:8,8:]=B;E=expm(E*.02);Ad=E[:8,:8];Bd=E[:8,8:]
 Jc=np.r_[np.array([(totalcom(xe+np.eye(4)[j]*1e-4)[0]-totalcom(xe-np.eye(4)[j]*1e-4)[0])/2e-4 for j in range(4)]),np.zeros(4)]
 Q=np.diag([20,100,1,5,1,3,.05,.05])+2000*np.outer(Jc,Jc);R=np.diag([1,1,1]);P=solve_discrete_are(Ad,Bd,Q,R);K=np.linalg.solve(R+Bd.T@P@Bd,Bd.T@P@Ad)
 print('eq',xe,'ue',ue,'tau',tau,'g',G,'mass',mass.sum(), 'COMJac',Jc);print('M',M,'eig',np.linalg.eigvals(Ad));print('K',K)
 return xe,ue,Ad,Bd,K
if __name__=='__main__':
 xe,ue,Ad,Bd,K=model();state=np.array([0,.01664,-.39335,.799915,0,0,0,0]);ref=np.r_[xe,np.zeros(4)];
 for i in range(1000):
  u=np.clip(ue-K@(state-ref),[-.95,-.1,-.87],[.5,1.05,.52]);state=ref+Ad@(state-ref)+Bd@(u-ue)
  if i in [0,4,9,19,49,99,499,999]:print(i,np.round(state,4),np.round(u,3))
 np.savez('/app/output/mechanical.npz',xe=xe,ue=ue,Ad=Ad,Bd=Bd,K=K)
